#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse,json,struct\nfrom pathlib import Path\ndef u16(b,o):return struct.unpack_from("<H",b,o)[0]\ndef u32(b,o):return struct.unpack_from("<I",b,o)[0]\ndef cstr(b,o):e=b.find(b"\\0",o);return b[o:e if e>=0 else len(b)].decode("ascii","replace")\ndef main():\n ap=argparse.ArgumentParser();ap.add_argument("exe",type=Path);ap.add_argument("--game-dir",type=Path);a=ap.parse_args();b=a.exe.read_bytes()\n if b[:2]!=b"MZ":raise SystemExit("not MZ")\n pe=u32(b,0x3c)\n if b[pe:pe+4]!=b"PE\\0\\0":raise SystemExit("bad PE")\n machine=u16(b,pe+4);nsec=u16(b,pe+6);optsz=u16(b,pe+20);oh=pe+24\n if machine!=0x14c or u16(b,oh)!=0x10b:raise SystemExit("not PE32/i386")\n base=u32(b,oh+28);entry=u32(b,oh+16);size=u32(b,oh+56);dirs=u32(b,oh+92);sections=[];sh=oh+optsz\n for _ in range(nsec):\n  name=b[sh:sh+8].split(b"\\0",1)[0].decode("ascii","replace");vs=u32(b,sh+8);rawsz=u32(b,sh+16);raw=u32(b,sh+20);va=u32(b,sh+12);sections.append({"name":name,"rva":hex(va),"virtual_size":vs,"raw_size":rawsz,"raw_offset":raw});sh+=40\n def rf(rva):\n  for s in sections:\n   start=int(s["rva"],16);span=max(s["virtual_size"],s["raw_size"])\n   if start<=rva<start+span:return s["raw_offset"]+(rva-start)\n  return None\n imports=[]\n if dirs>1:\n  ir=u32(b,oh+96+8);p=rf(ir) if ir else None\n  while p is not None and p+20<=len(b):\n   oft=u32(b,p);nr=u32(b,p+12);iat=u32(b,p+16)\n   if not any((oft,nr,iat)):break\n   no=rf(nr);dll=cstr(b,no) if no is not None else "<bad>";funcs=[];tp=rf(oft or iat) if (oft or iat) else None\n   if tp is not None:\n    for j in range(8192):\n     v=u32(b,tp+j*4)\n     if not v:break\n     if v&0x80000000:funcs.append({"ordinal":v&0xffff})\n     else:\n      fo=rf(v);funcs.append({"name":cstr(b,fo+2) if fo is not None else "<bad>"})\n   imports.append({"dll":dll,"functions":funcs});p+=20\n dlls=[]\n if a.game_dir:\n  dlls=[str(x.relative_to(a.game_dir)) for x in sorted(a.game_dir.rglob("*.dll"))]\n print(json.dumps({"machine":"i386","entry_rva":hex(entry),"image_base":hex(base),"size_of_image":size,"sections":sections,"imports":imports,"bundled_dll_candidates":dlls},indent=2))\nif __name__=="__main__":main()\n